const SWORD_DUE_RE = /^F\d+ sword due: /

/**
 * The cell's own read - the sword due's raw count across the lines.
 * The sword due book's own beside-seat's count - the count this word
 * prices across the faces (the whole raw mass the lane prints - every
 * line rides, no exclusion the lane needs).
 *
 * @param {string[]|null} [lines] the face's own log lines
 * @returns {number} the sword due raw count (0 when the
 *   lines cannot prove a sword due line - the zero a lawful count)
 */
export function swordDues (lines) {
  if (!Array.isArray(lines)) return 0
  let n = 0
  for (const l of lines) {
    if (typeof l === 'string' && SWORD_DUE_RE.test(l)) n++
  }
  return n
}

